CREATE POLICY "documents_machine_attachment_scope" ON "documents" AS RESTRICTIVE FOR ALL TO "app_runtime" USING (("documents"."related_entity_type" is distinct from 'machine_installation' or exists (select 1 from public.machine_installations m where m.id = "documents"."related_entity_id" and m.org_id = "documents"."org_id"))) WITH CHECK (("documents"."related_entity_type" is distinct from 'machine_installation' or exists (select 1 from public.machine_installations m where m.id = "documents"."related_entity_id" and m.org_id = "documents"."org_id")));